import { describe, expect, it } from 'vitest';
import { languageFor } from './codemirror';

describe('languageFor', () => {
  it('finds TypeScript by extension', () => {
    expect(languageFor('a.ts')?.name).toBe('typescript');
  });

  it('highlights a file it has no language for as plain text', () => {
    expect(languageFor('notes.unknownext')?.name).toBe('plain');
  });
});

