use gpui::{div, IntoElement, ParentElement};

pub struct Run {
    pub workflow: String,
    pub branch: String,
}

pub fn filters(this_branch_only: bool) -> impl IntoElement {
    div()
        .child("All runs")
        .child(if this_branch_only { "This branch (on)" } else { "This branch" })
}

pub fn runs(runs: &[Run], branch: &str, this_branch_only: bool) -> Vec<String> {
    runs.iter()
        .filter(|run| !this_branch_only || run.branch == branch)
        .map(|run| format!("{} on {}", run.workflow, run.branch))
        .collect()
}
